def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5, 5, 5, 5]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
             fmt([10**9, -10**9]), fmt([-10**9, -10**9, 10**9, 0]), fmt([7, 7, 3, 3, 9, 9, 3])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([3, 10, 100])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(1000)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-50, 50) for _ in range(100000)]))
    tests.append(fmt([10**9 - i for i in range(100000)]))
    return tests

